import{_ as e,o as t,c as o,ae as r}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"ja/reference/faq.md","filePath":"ja/reference/faq.md"}'),s={name:"ja/reference/faq.md"};function i(l,a,h,d,n,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to &quot;よくある質問&quot;">​</a></h1><h2 id="orchestraは無料ですか" tabindex="-1">Orchestraは無料ですか？ <a class="header-anchor" href="#orchestraは無料ですか" aria-label="Permalink to &quot;Orchestraは無料ですか？&quot;">​</a></h2><p>はい。Orchestraは完全に無料で使用できます。</p><h2 id="データはどこかに送信されますか" tabindex="-1">データはどこかに送信されますか？ <a class="header-anchor" href="#データはどこかに送信されますか" aria-label="Permalink to &quot;データはどこかに送信されますか？&quot;">​</a></h2><p>いいえ。全てのデータはローカルマシンに保存されます。hookサーバーは<code>localhost:3008</code>で動作し、ローカルのClaude Codeセッションからの接続のみ受け付けます。外部サーバーへのデータ送信は一切ありません。</p><h2 id="どのaiコーディングエージェントに対応していますか" tabindex="-1">どのAIコーディングエージェントに対応していますか？ <a class="header-anchor" href="#どのaiコーディングエージェントに対応していますか" aria-label="Permalink to &quot;どのAIコーディングエージェントに対応していますか？&quot;">​</a></h2><p>現在、Hooks機能を通じて<strong>Claude Code</strong>をサポートしています。将来的に他のエージェントへの対応も検討しています。</p><h2 id="システム要件は" tabindex="-1">システム要件は？ <a class="header-anchor" href="#システム要件は" aria-label="Permalink to &quot;システム要件は？&quot;">​</a></h2><ul><li>macOS 11.0+（Big Sur以降）</li><li>Apple Silicon（M1/M2/M3/M4）</li><li>tmux（セッションジャンプ用）</li><li>Claude Code（インストール済み）</li></ul><h2 id="インストール方法は" tabindex="-1">インストール方法は？ <a class="header-anchor" href="#インストール方法は" aria-label="Permalink to &quot;インストール方法は？&quot;">​</a></h2><p>Homebrewでのインストールを推奨しています:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zeroshotlog/tap/orchestra</span></span></code></pre></div><p>または<a href="https://github.com/zeroshotlog/orchestra/releases" target="_blank" rel="noreferrer">Releasesページ</a>からDMGをダウンロードしてください。</p><h2 id="アンインストール方法は" tabindex="-1">アンインストール方法は？ <a class="header-anchor" href="#アンインストール方法は" aria-label="Permalink to &quot;アンインストール方法は？&quot;">​</a></h2><ol><li>Orchestraが実行中の場合は終了</li><li><code>/Applications</code>から<code>Orchestra.app</code>を削除</li><li><code>~/.claude/settings.json</code>からhook設定を削除</li></ol><h2 id="tmuxなしでも使えますか" tabindex="-1">tmuxなしでも使えますか？ <a class="header-anchor" href="#tmuxなしでも使えますか" aria-label="Permalink to &quot;tmuxなしでも使えますか？&quot;">​</a></h2><p>tmuxなしでもセッションの監視は可能ですが、「セッションにジャンプ」機能はtmuxが必要です。tmux外で実行されているセッションはダッシュボードに表示されますが、Jumpボタンは使用できません。</p><h2 id="claude-codeのagent-teams機能に対応していますか" tabindex="-1">Claude CodeのAgent Teams機能に対応していますか？ <a class="header-anchor" href="#claude-codeのagent-teams機能に対応していますか" aria-label="Permalink to &quot;Claude CodeのAgent Teams機能に対応していますか？&quot;">​</a></h2><p>はい。Claude CodeのAgent Teams機能を使用すると、Orchestraは同じtmuxウィンドウ内で実行されているチームメンバーを自動検出します。チームセッションは虹色のボーダーで表示され、LeadとMemberのロールが明確にラベル付けされます。チーム検出が動作するには、<code>TeammateIdle</code>と<code>TaskCompleted</code>のhookが設定されている必要があります。</p><h2 id="hookイベントはいくつ設定する必要がありますか" tabindex="-1">hookイベントはいくつ設定する必要がありますか？ <a class="header-anchor" href="#hookイベントはいくつ設定する必要がありますか" aria-label="Permalink to &quot;hookイベントはいくつ設定する必要がありますか？&quot;">​</a></h2><p>全機能を利用するには、13個のhookイベントを設定してください: PreToolUse, PostToolUse, Stop, Notification, SubagentStart, SubagentStop, SessionStart, SessionEnd, UserPromptSubmit, PermissionRequest, PreCompact, TeammateIdle, TaskCompleted。詳細な設定は<a href="/orchestra/docs/ja/guide/getting-started.html">はじめに</a>ガイドを参照してください。</p><h2 id="サブエージェントの追跡はできますか" tabindex="-1">サブエージェントの追跡はできますか？ <a class="header-anchor" href="#サブエージェントの追跡はできますか" aria-label="Permalink to &quot;サブエージェントの追跡はできますか？&quot;">​</a></h2><p>はい。Claude CodeがTaskツールでサブエージェントを起動すると、Orchestraはセッションごとのアクティブサブエージェント数を追跡します。セッションカードには現在のサブエージェント数が表示され、「Delegating」アクティビティステータスになります。</p><h2 id="グリッド表示とリスト表示を切り替えられますか" tabindex="-1">グリッド表示とリスト表示を切り替えられますか？ <a class="header-anchor" href="#グリッド表示とリスト表示を切り替えられますか" aria-label="Permalink to &quot;グリッド表示とリスト表示を切り替えられますか？&quot;">​</a></h2><p>はい。<code>⌘1</code>でグリッド表示、<code>⌘2</code>でリスト表示に切り替えるか、<strong>View</strong>メニューから選択できます。グリッド表示は詳細なセッションカード、リスト表示はコンパクトな行ベースのレイアウトです。</p><h2 id="ポモドーロタイマーとは" tabindex="-1">ポモドーロタイマーとは？ <a class="header-anchor" href="#ポモドーロタイマーとは" aria-label="Permalink to &quot;ポモドーロタイマーとは？&quot;">​</a></h2><p>集中作業セッションの管理をサポートするポモドーロタイマーを内蔵しています。Work/Breakの時間、サイクル数、タイマーサイズを<strong>Orchestra</strong>メニュー → <strong>Pomodoro Timer</strong>からカスタマイズ可能です。ドラッグ&amp;ドロップでの位置変更やWork/Breakの自動サイクルに対応しています。</p><h2 id="エージェントバッジとは" tabindex="-1">エージェントバッジとは？ <a class="header-anchor" href="#エージェントバッジとは" aria-label="Permalink to &quot;エージェントバッジとは？&quot;">​</a></h2><p>各セッションで動作中のAIコーディングエージェント（Claude, Codex, Gemini等）を表示するバッジです。hookイベントから自動的に検出されます。バッジの表示/非表示は<strong>Orchestra</strong>メニュー → <strong>Show Agent Badges</strong>から切り替えられます。</p><h2 id="セッションの検索やフィルターはできますか" tabindex="-1">セッションの検索やフィルターはできますか？ <a class="header-anchor" href="#セッションの検索やフィルターはできますか" aria-label="Permalink to &quot;セッションの検索やフィルターはできますか？&quot;">​</a></h2><p>はい。<code>⌘F</code>で検索バーにフォーカスし、タイトルでセッションをフィルターできます。複数のtmuxセッションが検出されると、上部にタブが表示され、tmuxセッション単位でのフィルターが可能です。</p>',31)])])}const m=e(s,[["render",i]]);export{u as __pageData,m as default};
